#include "history_schema.h"

Z6MoveHistoryJson& Z6MoveHistoryJson::operator=(const Z6MoveHistoryJson& other) {
    if (this != &other) {
        move_ = other.move_;
        move_valid_ = other.move_valid_;
        details_ = other.details_;
        details_valid_ = other.details_valid_;
    }
    return *this;
}

bool Z6MoveHistoryJson::validate(const std::string& json_str) {
    try {
        auto j = json::parse(json_str);
        if (!j.is_object()) return false;
        if (!j.contains("Move")) return false;
        if (j.contains("Move")) {
            if (!j["Move"].is_object()) return false;
        }
        if (j.contains("Details")) {
            if (!j["Details"].is_array()) return false;
        }
        return true;
    } catch (...) {
        return false;
    }
}

bool Z6MoveHistoryJson::getMove(Z6MoveJson& val) const {
    if (!move_valid_) return false;
    val = move_;
    return true;
}

bool Z6MoveHistoryJson::getDetails(size_t index, Z6DetailJson& val) const {
    if (!details_valid_ || index >= details_.size()) return false;
    val = details_[index];
    return true;
}

bool Z6MoveHistoryJson::getDetailsVector(std::vector<Z6DetailJson>& val) const {
    if (!details_valid_) return false;
    val = details_;
    return true;
}

void Z6MoveHistoryJson::setMove(const Z6MoveJson& val) {
    move_ = val;
    move_valid_ = true;
}

void Z6MoveHistoryJson::setDetails(const std::vector<Z6DetailJson>& val) {
    details_ = val;
    details_valid_ = true;
}

void Z6MoveHistoryJson::from_json(const std::string& json_str) {
    json j = json::parse(json_str);
        if (j.contains("Move")) {
            move_.from_json(j["Move"].dump());
            move_valid_ = true;
        }
        if (j.contains("Details")) {
            details_.clear();
            for (const auto& item : j["Details"]) {
                Z6DetailJson obj;
                obj.from_json(item.dump());
                details_.push_back(obj);
            }
            details_valid_ = true;
        }
}

std::string Z6MoveHistoryJson::to_json() const {
    json j;
        if (move_valid_) {
            j["Move"] = json::parse(move_.to_json());
        }
        if (details_valid_) {
            json arr = json::array();
            for (const auto& item : details_) {
                arr.push_back(json::parse(item.to_json()));
            }
            j["Details"] = arr;
        }
    return j.dump();
}

